### Repro Code

```TypeScript
export const truthy = <T>(value: Awaited<T>) => (value ? 1 : 2);
export const nullish = <T>(value: Awaited<T>) => value ?? 1;

export const fromPromise = async <T>(promise: Promise<T>) => {
  const value = await promise;
  return value ? 1 : 2;
};
```

### ESLint Config

```javascript
import tseslint from 'typescript-eslint';

export default [
  {
    files: ['**/*.ts'],
    languageOptions: {
      parser: tseslint.parser,
      parserOptions: {projectService: true, tsconfigRootDir: import.meta.dirname},
    },
    plugins: {'@typescript-eslint': tseslint.plugin},
    rules: {'@typescript-eslint/no-unnecessary-condition': 'error'},
  },
];
```

### tsconfig

```jsonc
{
  "compilerOptions": {
    "strict": true
  }
}
```

### Expected Result

No reports: `T` can be falsy.

### Actual Result

```
1:50  error  Unnecessary conditional, value is always truthy
2:50  error  Unnecessary conditional, expected left-hand side of `??` operator to be possibly null or undefined
6:10  error  Unnecessary conditional, value is always truthy
```

### Additional Info

AI generated finding:

`checker.getBaseConstraintOfType()` returns `undefined` for `Awaited<T>`.
Other conditional types with no resolvable constraint are reported the same way, e.g. `type Id<T> = T extends unknown ? T : never`.

